CREATE TABLE IF NOT EXISTS public.users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email text NOT NULL UNIQUE,
  name text,
  avatar text,
  age integer,
  weight numeric,
  height numeric,
  "fitnessGoal" text,
  "totalCalories" numeric DEFAULT 0,
  "totalDistance" numeric DEFAULT 0,
  "totalWorkouts" integer DEFAULT 0,
  "joinDate" timestamptz DEFAULT now(),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view their own profile" ON public.users
  FOR SELECT USING (auth.uid() = id);

CREATE POLICY "Users can update their own profile" ON public.users
  FOR UPDATE USING (auth.uid() = id);

CREATE INDEX IF NOT EXISTS idx_users_email ON public.users(email);
CREATE INDEX IF NOT EXISTS idx_users_id ON public.users(id);

CREATE TABLE IF NOT EXISTS public.activities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  type text NOT NULL,
  "startTime" timestamptz,
  "endTime" timestamptz,
  duration numeric,
  distance numeric,
  calories numeric,
  pace numeric,
  intensity text,
  notes text,
  timestamp timestamptz DEFAULT now(),
  status text DEFAULT 'completed',
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view their own activities" ON public.activities
  FOR SELECT USING (auth.uid() = "userId");

CREATE POLICY "Users can insert their own activities" ON public.activities
  FOR INSERT WITH CHECK (auth.uid() = "userId");

CREATE POLICY "Users can update their own activities" ON public.activities
  FOR UPDATE USING (auth.uid() = "userId");

CREATE POLICY "Users can delete their own activities" ON public.activities
  FOR DELETE USING (auth.uid() = "userId");

CREATE INDEX IF NOT EXISTS idx_activities_userId ON public.activities("userId");
CREATE INDEX IF NOT EXISTS idx_activities_timestamp ON public.activities(timestamp);
CREATE INDEX IF NOT EXISTS idx_activities_startTime ON public.activities("startTime");

CREATE TABLE IF NOT EXISTS public.goals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  type text NOT NULL,
  target text,
  "targetValue" numeric,
  "startDate" timestamptz,
  "endDate" timestamptz,
  progress numeric DEFAULT 0,
  status text DEFAULT 'active',
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE public.goals ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view their own goals" ON public.goals
  FOR SELECT USING (auth.uid() = "userId");

CREATE POLICY "Users can insert their own goals" ON public.goals
  FOR INSERT WITH CHECK (auth.uid() = "userId");

CREATE POLICY "Users can update their own goals" ON public.goals
  FOR UPDATE USING (auth.uid() = "userId");

CREATE POLICY "Users can delete their own goals" ON public.goals
  FOR DELETE USING (auth.uid() = "userId");

CREATE INDEX IF NOT EXISTS idx_goals_userId ON public.goals("userId");
CREATE INDEX IF NOT EXISTS idx_goals_status ON public.goals(status);

CREATE TABLE IF NOT EXISTS public.achievements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  badge text,
  title text NOT NULL,
  description text,
  icon text,
  "unlockedDate" timestamptz,
  "isUnlocked" boolean DEFAULT false,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE public.achievements ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view their own achievements" ON public.achievements
  FOR SELECT USING (auth.uid() = "userId");

CREATE POLICY "Users can insert their own achievements" ON public.achievements
  FOR INSERT WITH CHECK (auth.uid() = "userId");

CREATE POLICY "Users can update their own achievements" ON public.achievements
  FOR UPDATE USING (auth.uid() = "userId");

CREATE INDEX IF NOT EXISTS idx_achievements_userId ON public.achievements("userId");
CREATE INDEX IF NOT EXISTS idx_achievements_isUnlocked ON public.achievements("isUnlocked");

CREATE TABLE IF NOT EXISTS public.daily_stats (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  date date NOT NULL,
  "totalCalories" numeric DEFAULT 0,
  "totalDistance" numeric DEFAULT 0,
  "totalDuration" numeric DEFAULT 0,
  "activityCount" integer DEFAULT 0,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  UNIQUE("userId", date)
);

ALTER TABLE public.daily_stats ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view their own daily stats" ON public.daily_stats
  FOR SELECT USING (auth.uid() = "userId");

CREATE POLICY "Users can insert their own daily stats" ON public.daily_stats
  FOR INSERT WITH CHECK (auth.uid() = "userId");

CREATE POLICY "Users can update their own daily stats" ON public.daily_stats
  FOR UPDATE USING (auth.uid() = "userId");

CREATE INDEX IF NOT EXISTS idx_daily_stats_userId ON public.daily_stats("userId");
CREATE INDEX IF NOT EXISTS idx_daily_stats_date ON public.daily_stats(date);
CREATE INDEX IF NOT EXISTS idx_daily_stats_userId_date ON public.daily_stats("userId", date);

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.users (id, email, name, avatar, age, weight, height, "fitnessGoal", "totalCalories", "totalDistance", "totalWorkouts", "joinDate", created_at, updated_at)
  VALUES (
    NEW.id,
    NEW.email,
    NEW.raw_user_meta_data ->> 'name',
    NEW.raw_user_meta_data ->> 'avatar',
    COALESCE((NEW.raw_user_meta_data ->> 'age')::integer, NULL),
    COALESCE((NEW.raw_user_meta_data ->> 'weight')::numeric, NULL),
    COALESCE((NEW.raw_user_meta_data ->> 'height')::numeric, NULL),
    NEW.raw_user_meta_data ->> 'fitnessGoal',
    COALESCE((NEW.raw_user_meta_data ->> 'totalCalories')::numeric, 0),
    COALESCE((NEW.raw_user_meta_data ->> 'totalDistance')::numeric, 0),
    COALESCE((NEW.raw_user_meta_data ->> 'totalWorkouts')::integer, 0),
    now(),
    now(),
    now()
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- === Deterministic CRUD policies for user-owned tables (generated by SupabaseConfigAgent) ===
